    if is_func_mode {
        // parse places if present
        if let Some(s) = places_str_opt {
            match s.parse::<usize>() {
                Ok(v) => places_val = v,
                Err(e) => {
                    let kind_debug = format!("{:?}", e);
                    eprintln!("-p, --places <integer> expected. {}", kind_debug);
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        } else {
            places_val = 4;
        }
        // parse func
        if let Some(s) = func_str_opt {
            match s.parse::<usize>() {
                Ok(v) => func_val = v,
                Err(e) => {
                    let kind_debug = format!("{:?}", e);
                    eprintln!("-u, --func <integer> expected. {}", kind_debug);
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        // func mode: output func, ignore files
        output_func(func_val, places_val);
        return;
    } else {
        // not func mode: parse cols
        if let Some(s) = cols_str_opt {
            match s.parse::<usize>() {
                Ok(v) => cols_val = v,
                Err(e) => {
                    let kind_debug = format!("{:?}", e);
                    eprintln!("-c, --cols <integer> expected. {}", kind_debug);
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        } else {
            cols_val = 10;
        }
        // parse len
        if let Some(s) = len_str_opt {
            match s.parse::<usize>() {
                Ok(v) => {
                    if v == 0 {
                        len_val = None; // 0 means all
                    } else {
                        len_val = Some(v);
                    }
                }
                Err(e) => {
                    let kind_debug = format!("{:?}", e);
                    eprintln!("-l, --len <integer> expected. {}", kind_debug);
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        } else {
            len_val = None;
        }
        // places ignored when not func mode (no parsing, no error even if invalid)
    }

    // At this point, check array mode
    if let Some(arr) = array_opt {
        // array mode: need data
        let data = read_input(input_opt, len_val);
        output_array(arr, &data, cols_val);
        return;
    }

    // hex mode
    let format_str = format_opt.map(|s| s.as_str()).unwrap_or("x");
    let prefix_enabled = match prefix_opt.map(|s| s.as_str()) {
        Some("0") => false,
        Some("1") => true,
        None => true,
        _ => true,
    };
    // color
    let color_enabled = match color_opt.map(|s| s.as_str()) {
        Some("0") => false,
        Some("1") => true,
        None => {
            // auto: tty and NO_COLOR not set
            let is_tty = std::io::stdout().is_terminal();
            let no_color_set = std::env::var_os("NO_COLOR").is_some();
            is_tty && !no_color_set
        }
        _ => false,
    };

    let data = read_input(input_opt, len_val);
    output_hex(&data, cols_val, format_str, prefix_enabled, color_enabled);
}

fn read_input(input_opt: Option<&String>, len_val: Option<usize>) -> Vec<u8> {
    let mut data: Vec<u8> = Vec::new();
    if let Some(path) = input_opt {
        match std::fs::read(path) {
            Ok(d) => data = d,
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        // read stdin
        let stdin = std::io::stdin();
        let mut handle = stdin.lock();
        // read to end
        if let Err(e) = handle.read_to_end(&mut data) {
            eprintln!("error: {}", e);
            std::process::exit(1);
        }
    }
    // truncate to len if needed
    if let Some(l) = len_val {
        if data.len() > l {
            data.truncate(l);
        }
    }
    data
}

fn format_octet(b: u8, format_str: &str, prefix_enabled: bool) -> String {
    match format_str {
        "o" => {
            if prefix_enabled {
                format!("0o{:04o}", b)
            } else {
                format!("{:04o}", b)
            }
        }
        "X" => {
            if prefix_enabled {
                format!("0x{:02X}", b)
            } else {
                format!("{:02X}", b)
            }
        }
        "b" => {
            if prefix_enabled {
                format!("0b{:08b}", b)
            } else {
                format!("{:08b}", b)
            }
        }
        _ => {
            // "x" default
            if prefix_enabled {
                format!("0x{:02x}", b)
            } else {
                format!("{:02x}", b)
            }
        }
    }
}

fn color_wrap(text: &str, code: u32) -> String {
    format!("\x1b[38;5;{}m{}\x1b[0m", code, text)
}

fn output_hex(data: &[u8], cols: usize, format_str: &str, prefix_enabled: bool, color_enabled: bool) {
    let cols_original = cols;
    let cols_eff = if cols == 0 { 1 } else { cols };
    let total = data.len();
    let mut out = String::new();
    // Use stdout lock? We'll build string and print at once, but for huge cols/data, building string could be large. Use print! directly.
    // For simplicity, write directly to stdout via print!
    // But to handle panic case? We'll just write.
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();

    if total == 0 {
        // one empty line
        let addr = 0;
        let _ = write!(handle, "0x{:06x}: ", addr);
        // padding: cols_original *5 spaces
        // For cols=0, 0 spaces. For others, cols*5.
        // Use repeat, but avoid huge allocation panic? Just repeat.
        let pad = cols_original.saturating_mul(5);
        // To replicate original panic for huge cols? Original panics with "Formatting argument out of range" for huge.
        // Our repeat would try to allocate huge and may OOM. Instead, we could mimic panic for very large?
        // For now, just repeat.
        if pad > 0 {
            let _ = write!(handle, "{}", " ".repeat(pad));
        }
        // No ascii? Actually empty line has no ascii, but original shows trailing space? The line is "0x000000: " + pad spaces? For empty with cols10, pad 50, line is "0x000000: " + 50 spaces. That's what we do. Note there is no extra? The prefix "0x...: " already includes one space after colon. Then pad spaces. No ascii.
        // But need to check: for empty, does line end with space? Yes, after pad, no ascii, just newline. Our write adds pad then newline.
        let _ = writeln!(handle, "");
        let _ = writeln!(handle, "   bytes: {}", total);
        return;
    }

    // non-empty: iterate chunks
    let mut addr: usize = 0;
    let chunks: Vec<&[u8]> = data.chunks(cols_eff).collect();
    for (idx, chunk) in chunks.iter().enumerate() {
        let _ = write!(handle, "0x{:06x}: ", addr);
        // hex part
        for b in chunk.iter() {
            let s = format_octet(*b, format_str, prefix_enabled);
            if color_enabled {
                let code = if *b == 0 { 22 } else { *b as u32 };
                let _ = write!(handle, "{} ", color_wrap(&s, code));
            } else {
                let _ = write!(handle, "{} ", s);
            }
        }
        // padding for missing
        let missing = cols_original.saturating_sub(chunk.len());
        if missing > 0 {
            // each missing is 5 spaces
            let pad = missing.saturating_mul(5);
            let _ = write!(handle, "{}", " ".repeat(pad));
        }
        // ascii part
        for b in chunk.iter() {
            let ch = if *b >= 0x20 && *b <= 0x7e {
                *b as char
            } else {
                '.'
            };
            // For color, wrap each char? Note: for '.' vs actual char, same wrapping with code.
            // For space (0x20), ch is ' ', still wrapped? Original wraps space as well: \x1b[38;5;32m \x1b[0m
            if color_enabled {
                let code = if *b == 0 { 22 } else { *b as u32 };
                // ch.to_string() for wrapping
                let s = ch.to_string();
                let _ = write!(handle, "{}", color_wrap(&s, code));
            } else {
                let _ = write!(handle, "{}", ch);
            }
        }
        let _ = writeln!(handle, "");
        addr += chunk.len();
        // Note: addr increment by chunk.len(), which for full chunks = cols_eff, for last partial = remainder.
        // For cols_eff vs cols_original difference only when cols==0, but then all chunks len 1, addr increments by 1, correct.
        let _ = idx;
    }
    // extra empty line if exact multiple
    if total % cols_eff == 0 {
        let _ = write!(handle, "0x{:06x}: ", addr);
        let pad = cols_original.saturating_mul(5);
        if pad > 0 {
            let _ = write!(handle, "{}", " ".repeat(pad));
        }
        let _ = writeln!(handle, "");
    }
    let _ = writeln!(handle, "   bytes: {}", total);
}

fn output_array(array_type: &str, data: &[u8], cols: usize) {
    let cols_eff = if cols == 0 { 1 } else { cols };
    let total = data.len();
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();

    // headers
    match array_type {
        "r" => {
            let _ = writeln!(handle, "let ARRAY: [u8; {}] = [", total);
        }
        "c" => {
            let _ = writeln!(handle, "unsigned char ARRAY[{}] = {{", total);
        }
        "g" => {
            let _ = writeln!(handle, "a := [{}]byte{{", total);
        }
        "p" => {
            let _ = writeln!(handle, "a = [");
        }
        "k" => {
            let _ = writeln!(handle, "val a = byteArrayOf(");
        }
        "j" => {
            let _ = writeln!(handle, "byte[] a = new byte[]{{");
        }
        "s" => {
            let _ = writeln!(handle, "let a: [UInt8] = [");
        }
        "f" => {
            let _ = writeln!(handle, "let a = [|");
        }
        _ => {}
    }

    if total == 0 {
        let _ = writeln!(handle, "    ");
        // footer
        match array_type {
            "r" => {
                let _ = writeln!(handle, "];");
            }
            "c" => {
                let _ = writeln!(handle, "}};");
            }
            "g" => {
                let _ = writeln!(handle, "}}");
            }
            "p" => {
                let _ = writeln!(handle, "]");
            }
            "k" => {
                let _ = writeln!(handle, ")");
            }
            "j" => {
                let _ = writeln!(handle, "}};");
            }
            "s" => {
                let _ = writeln!(handle, "]");
            }
            "f" => {
                let _ = writeln!(handle, "|]");
            }
            _ => {}
        }
        return;
    }

    let chunks: Vec<&[u8]> = data.chunks(cols_eff).collect();
    for (idx, chunk) in chunks.iter().enumerate() {
        let is_last_chunk = idx == chunks.len() - 1;
        let _ = write!(handle, "    ");
        for (j, b) in chunk.iter().enumerate() {
            let is_last_item = is_last_chunk && j == chunk.len() - 1;
            match array_type {
                "g" => {
                    let s = format!("0x{:02x}", b);
                    let _ = write!(handle, "{}, ", s);
                }
                "f" => {
                    let s = format!("0x{:02x}uy", b);
                    if is_last_item {
                        let _ = write!(handle, "{}", s);
                    } else {
                        let _ = write!(handle, "{}; ", s);
                    }
                }
                _ => {
                    let s = format!("0x{:02x}", b);
                    if is_last_item {
                        let _ = write!(handle, "{}", s);
                    } else {
                        let _ = write!(handle, "{}, ", s);
                    }
                }
            }
        }
        let _ = writeln!(handle, "");
    }
    // extra blank indent if exact multiple
    if total % cols_eff == 0 {
        let _ = writeln!(handle, "    ");
    }

    // footer
    match array_type {
        "r" => {
            let _ = writeln!(handle, "];");
        }
        "c" => {
            let _ = writeln!(handle, "}};");
        }
        "g" => {
            let _ = writeln!(handle, "}}");
        }
        "p" => {
            let _ = writeln!(handle, "]");
        }
        "k" => {
            let _ = writeln!(handle, ")");
        }
        "j" => {
            let _ = writeln!(handle, "}};");
        }
        "s" => {
            let _ = writeln!(handle, "]");
        }
        "f" => {
            let _ = writeln!(handle, "|]");
        }
        _ => {}
    }
}

fn output_func(func_len: usize, places: usize) {
    use std::io::Write;
    let stdout = std::io::stdout();
    let mut handle = stdout.lock();
    if func_len == 0 {
        let _ = writeln!(handle, "");
        return;
    }
    // generate values
    let mut vals: Vec<String> = Vec::with_capacity(func_len);
    for i in 0..func_len {
        let v = ((i as f64) * std::f64::consts::PI / (2.0 * func_len as f64)).sin();
        let s = format!("{:.prec$}", v, prec = places);
        vals.push(s);
    }
    // chunk by 10
    let chunks: Vec<&[String]> = vals.chunks(10).collect();
    for chunk in chunks.iter() {
        for s in chunk.iter() {
            let _ = write!(handle, "{},", s);
        }
        let _ = writeln!(handle, "");
    }
    if func_len % 10 == 0 {
        let _ = writeln!(handle, "");
    }
}
RS
"}

